// kk — Қазақша (cazaque), na escrita CIRÍLICA.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ESCRITA: a cirílica. O Cazaquistão decidiu migrar para o latino (decreto de 2017, revisto em 2021) e
// a troca está em andamento — mas o que o navegador manda como "kk", e o que a maioria lê hoje, é o
// cirílico. Se um dia a migração terminar, o caminho é um dicionário "kk-Latn" ao lado, não trocar este.
//
// NÃO É O RUSSO. Divide o alfabeto e muita palavra emprestada, e copiar do ru.ts é o erro que passaria
// em todo teste: o cazaque tem nove letras próprias (ә ғ қ ң ө ұ ү һ і), é aglutinante, põe o verbo no
// fim e não tem gênero.
//
// TOM: **сіз**, nunca *сен* — a mesma escolha do uzbeque, que é parente: o *сен* é de família e de
// amigo antigo, e com quem acabou de chegar soa atrevido. O *сіз* é o neutro entre adultos, e é o que as
// interfaces em cazaque usam.
//
// BOTÕES vão no substantivo verbal (Сақтау, Жіберу, Болдырмау), que não tem pessoa; as FRASES que falam
// com a pessoa vão no imperativo de cortesia (таңдаңыз, жазыңыз).
//
// GÊNERO: NENHUM, como no turco e no uzbeque — nem no "você", nem no "ele/ela" (ол), nem no verbo.
//
// NÚMEROS: o substantivo depois do número fica no singular ("5 хабарлама"). `Intl.NumberFormat('kk')`
// devolve `1 234 567` — latinos, com espaço.
//
// VOCABULÁRIO, decidido uma vez: comunidade = қауымдастық, canal = арна, sala de voz = дауыс бөлмесі,
// chamada = қоңырау, conversa = әңгіме, mensagem = хабарлама, senha = құпиясөз, lixeira = себет, tópico
// = тақырып, conta = аккаунт, administrador = әкімші, dono = иесі, cargo = рөл, convite = шақыру, perfil
// = профиль, transmissão = трансляция, tela = экран, membro = мүше, pacote = жинақ, enquete =
// сауалнама, denúncia = шағым, vila = ауыл, guarda-roupa = гардероб, cutucada = түрту, recado (da tela
// de boas-vindas e do aviso) = хабарландыру.
//
// SOM E VOZ SÃO DUAS PALAVRAS: дауыс é a voz, дыбыс é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = мөр (o da comunidade), insígnia = төсбелгі (a da pessoa).

