    'Бөлмедегі кез келген адам жібере алатын конфетти, отшашу және жүрекшелер. Қоңырау кезінде компьютеріңіз қатып қалса, өшіріңіз — өшірулі болса, сіз оларды көрмейсіз де, жібермейсіз де.',
