  'Descartar': 'Тастау',
  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.':
    'Syden-ді барлық басқа компьютерлер мен телефондарда ажыратады. Сіз мұнда қосулы қаласыз.',
  'Desconectando…': 'Ажыратылуда…',
  'Desconectar': 'Ажырату',
  'Descrição': 'Сипаттама',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'Өшірулі болса, бөлмедегілердің трансляциясы шақыру ретінде көрінеді және тек сіз Көру батырмасын басқанда ғана жүктеле бастайды. Бұл интернет пен процессорды үнемдейді — әсіресе толы бөлмеде.',
