  'O sorteio de {premio} terminou sem participantes.': '{premio} ұтыс ойыны қатысушысыз аяқталды.',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden арнада жүлдені жариялайды, қатысқысы келетін адам 🎉 арқылы реакция береді. Белгіленген уақытта реакция бергендер арасынан ұтыс өткізіп, нәтижені жариялайды.',
  'Participantes: {n}': 'Қатысушылар: {n}',
  'Prêmio': 'Жүлде',
  'Quem ganhou: {nomes}': 'Жеңімпаз: {nomes}',
