  'Aniversário': 'Туған күн',
  'Aniversários': 'Туған күндер',
  'Canal dos parabéns': 'Құттықтау арнасы',
  'Dia': 'Күн',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Бүгін {pessoa} туған күні! 🎉 Құтты болсын!',
  'Mês': 'Ай',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Күнін енгізген адамның туған күнінде Syden таңдалған арнаға құттықтау жариялайды. Есімнің орнына {pessoa} қолданыңыз.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Тек күн мен ай, жыл ешқашан. Туған күндерді хабарлайтын қауымдастықтар сол күні құттықтайды. Міндетті емес, қалаған кезде өшіруге болады.',
  'Texto dos parabéns': 'Құттықтау мәтіні',
