  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'Әр адам арнада хабарламалар арасында қанша күтеді.',
  'Regras': 'Ережелер',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Хабарлама шықпай тұрып Syden өзі қолданатын ережелер. Әкімшілерге қолданылмайды. Бұғатталған хабарлама себебімен бірге жазған адамға қайтады, оны басқа ешкім көрмейді.',
  'Salvo.': 'Сақталды.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Әр жолға біреуден. Бүтін сөз есептеледі, екпін мен бас әріптің айырмашылығынсыз: бір сөзге тыйым салу оны жай ғана қамтитын ұзынырақ сөзді бұғаттамайды.',
