  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.':
    'Әзірге жинақ жоқ. Алғашқысын өз суреттеріңізден құрастырыңыз немесе осы қауымдастықта бар эмодзилерді жариялаңыз.',
