  'Sua senha, para confirmar que é você': 'Сіз екеніңізді растау үшін құпиясөзіңіз',
  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.':
    'Трансляцияңызда дыбыс жоқ. Браузер дыбысты экранды таңдау терезесінде «аудионы бөлісу» белгісін қойсаңыз ғана жібереді.',
