  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.':
    'Тек өзіңіздікін немесе пайдалануға құқығыңыз бар нәрсені жүктеңіз. Файлдың болуы оны басқаларға ойнатуға құқықтың болуымен бірдей емес.',
