  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.':
    'Біреу бөлмеңізге кіргенде немесе шыққанда, біреу экранын көрсете бастағанда және сіз микрофонды немесе дыбысты өшіргенде дыбыс ойнатады.',
