  'Toda letra com a mesma largura.': 'Барлық әріптің ені бірдей.',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'Барлық түстер баяу айналады. Ең көзге түсетіні.',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.':
    'Бұл қауымдастықтағы барлығы осы эмодзилерді {exemplo} деп жазып немесе чаттағы эмодзи батырмасы арқылы қолдана алады. Жазылымсыз: бәрі ашық.',
