  'Traz de volta os emojis que vêm com o Syden. O que vocês enviaram continua como está, e nada vira cópia repetida.':
    'Syden-мен бірге келетін эмодзилерді қайтарады. Сіздер жүктегендер сол күйінде қалады және ештеңе қайталанбайды.',
