  'último dia para trazer de volta': 'қайтарудың соңғы күні',
  'Um anel claro e discreto.': 'Ашық әрі қарапайым сақина.',
  'Um anel quente, cor de cobre velho.': 'Ескі мыс түстес жылы сақина.',
  'um canal': 'бір арна',
  'Um dos 25 primeiros': 'Алғашқы 25 адамның бірі',
  'Um halo discreto na cor do próprio nome.': 'Аттың өз түсіндегі қарапайым нұр шеңбері.',
  'Um lugar novo, com canais próprios, e você decide quem entra.': 'Өз арналары бар жаңа орын, ал кім кіретінін сіз шешесіз.',
  'Um lugar novo, com canais próprios. Você escolhe quem entra pelo código de convite.':
    'Өз арналары бар жаңа орын. Кім кіретінін шақыру коды арқылы сіз таңдайсыз.',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.':
    'Орнатылған жинақ бүкіл қауымдастыққа қосылады: оның эмодзилері барлығының хабарламаларында жұмыс істей бастайды.',
  'Uma cópia do que você escreveu fica 90 dias fora do app, para o caso de pedido de autoridade. Ninguém a lê pelo Syden.':
    'Жазғандарыңыздың көшірмесі құзырлы органдардың сұранысы үшін 90 күн қолданбадан тыс сақталады. Оны Syden арқылы ешкім оқымайды.',
  'Uma ideia sua entrou no Syden': 'Идеяларыңыздың бірі Syden-ге енді',
  'Uma imagem larga, de 1200 por 300 ou parecida. GIF animado vale, e anima de verdade. Sem capa, fica a arte que você escolheu nas boas-vindas.':
    '1200-ге 300 немесе соған жақын кең сурет. Анимациялық GIF те болады және шынымен қозғалады. Мұқаба болмаса, қарсы алу экранында таңдаған суретіңіз қалады.',
