  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Екі адам тақтаға кезекпен тас қояды. Бес тасты қатарынан тізген жеңеді. Бөлме тамашалайды.',
  'Mancala': 'Манкала',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'Егіс ойыны, тоғызқұмалақ сияқты: бір ұяның құмалақтарын алып, келесі ұяларға біреуден салыңыз. Қазынасына көбірек жинаған жеңеді. Бөлме тамашалайды.',
