  'Essa casa não está livre.': 'Бұл ұяшық бос емес.',
  'Escolha um número de 1 a 9.': '1-ден 9-ға дейінгі санды таңдаңыз.',
  'A mesa já está cheia.': 'Үстел толып қалды.',
  'Você já está na mesa.': 'Сіз үстел басында отырсыз.',
  'Você não está jogando.': 'Сіз ойнап жатқан жоқсыз.',
  'A partida não está em andamento.': 'Ойын жүріп жатқан жоқ.',
  'Você está assistindo esta partida.': 'Сіз бұл ойынды көріп отырсыз.',
  'Espere a sua vez.': 'Кезегіңізді күтіңіз.',
  'Essa casa já está ocupada.': 'Бұл нүкте бос емес.',
  'Escolha uma casa do seu lado.': 'Өз жағыңыздағы ұяны таңдаңыз.',
  'Essa casa está vazia.': 'Бұл ұя бос.',
  'Agora não é hora de votar.': 'Қазір дауыс беретін уақыт емес.',
  'Sala de voz não encontrada.': 'Дауыс бөлмесі табылмады.',
  'Jogo desconhecido.': 'Белгісіз ойын.',
  'Entre na sala de voz para jogar com a turma.': 'Достармен ойнау үшін дауыс бөлмесіне кіріңіз.',
  'Já tem uma partida acontecendo nesta sala.': 'Бұл бөлмеде ойын жүріп жатыр.',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'Ойынды мерзімінен бұрын тек оны бастаған адам ғана аяқтай алады.',
  'Lobisomem': 'Қасқыр-адам',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Түнде басқа қасқыр-адамдармен бірге кімге шабуыл жасайтыныңызды таңдаңыз. Күндіз ешкімнің күдіктенуіне жол бермеңіз.',
  'Vidente': 'Көріпкел',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Түнде біреудің қасқыр-адам екенін не емесін біліңіз. Тәуекелге тұрарлық деп ойласаңыз, күндіз айтыңыз.',
  'Anjo': 'Періште',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Түнде қорғайтын біреуді таңдаңыз. Қасқыр-адамдар сол адамға шабуыл жасаса, ол аман қалады.',
  'Da vila': 'Ауыл тұрғыны',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Түнде ұйықтаңыз. Күндіз қасқыр-адамдардың кім екенін анықтап, оларды ойыннан шығару үшін дауыс беріңіз.',
  'A vila venceu!': 'Ауыл жеңді!',
  'Os lobisomens venceram!': 'Қасқыр-адамдар жеңді!',
  'Noite {n}. A vila dorme.': '{n}-түн. Ауыл ұйықтап жатыр.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Түнде қасқыр-адамдар шабуыл жасады: {nome}.',
  'Ninguém morreu esta noite.': 'Бүгін түнде ешкім өлген жоқ.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': '{n}-күн. Сөйлесіп, қасқыр-адам деп ойлайтын адамға дауыс беріңіздер.',
  'A vila tirou {nome} do jogo.': 'Ауыл ойыннан шығарды: {nome}.',
  'Empate: ninguém sai hoje.': 'Тең: бүгін ешкім шықпайды.',
  'Clique em quem os lobisomens vão atacar.': 'Қасқыр-адамдар кімге шабуыл жасайтынын басыңыз.',
  'Você já usou a sua visão esta noite.': 'Бүгін түнде көріпкелдігіңізді пайдаландыңыз.',
  'Clique em alguém para descobrir se é lobisomem.': 'Қасқыр-адам екенін білу үшін біреуді басыңыз.',
  'Clique em quem você quer proteger esta noite.': 'Бүгін түнде кімді қорғағыңыз келсе, соны басыңыз.',
  'Durma. Os outros papéis estão agindo.': 'Ұйықтаңыз. Басқа рөлдер әрекет етіп жатыр.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Ойыннан шықтыңыз. Енді тек қарайсыз — ештеңе айтпаңыз!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Ойыннан кімді шығарғыңыз келсе, соны басыңыз. Ең көп дауыс алған шығады; тең болса, ешкім.',
  'é lobisomem': 'қасқыр-адам',
  'não é lobisomem': 'қасқыр-адам емес',
  'Ninguém hoje': 'Бүгін ешкім',
  'A solução do problema.': 'Есептің шешімі.',
  'Acertou! Agora é torcer pelos outros.': 'Дұрыс! Енді басқаларға жанкүйер болыңыз.',
  'Esse não era o lance. Espere a solução.': 'Бұл жүріс емес еді. Шешімді күтіңіз.',
  'Você joga com as brancas. Ache o melhor lance.': 'Сіз ақтармен ойнайсыз. Ең жақсы жүрісті табыңыз.',
  'Você joga com as pretas. Ache o melhor lance.': 'Сіз қаралармен ойнайсыз. Ең жақсы жүрісті табыңыз.',
  'Ver este problema no Lichess': 'Бұл есепті Lichess-те көру',
  'Problema do Lichess · nota {nota}': 'Lichess есебі · рейтинг {nota}',
  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'Әркім жасырын рөл алады. Түнде қасқыр-адамдар шабуыл жасайды; күндіз ауыл сөйлесіп, кімді ойыннан шығаруға дауыс береді. 4 немесе одан көп адам керек.',
  'Problemas de xadrez': 'Шахмат есептері',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'Барлығы бірдей Lichess есебін алады. Дұрыс жүрісті ең жылдам тапқан адам қосымша ұпай алады.',
  'Os problemas de xadrez não estão no servidor.': 'Шахмат есептері серверде жоқ.',
  'Este problema já acabou.': 'Бұл есеп аяқталып қойды.',
  'Lance inválido.': 'Жүріс жарамсыз.',
  'Solo': 'Жеке',
  'Coletivo': 'Бірге',
  'Palavra secreta': 'Құпия сөз',
  'Todo mundo tenta adivinhar a mesma palavra de 5 letras, em 6 chutes. A sala vê as cores dos outros, mas não as letras. Quem acertar com menos chutes ganha mais pontos.': 'Барлығы бірдей 5 әріпті сөзді 6 әрекетте табуға тырысады. Басқалардың түстерін көресіз, бірақ әріптерін емес. Азырақ әрекетпен тапқан көбірек ұпай алады.',
  'A palavra era: {palavra}': 'Сөз мынау еді: {palavra}',
  'Acabaram os seus chutes. Espere a palavra.': 'Әрекеттеріңіз таусылды. Сөзді күтіңіз.',
  'Escreva uma palavra de 5 letras e aperte Enter.': '5 әріпті сөз жазып, Enter басыңыз.',
  'Seu quadro': 'Сіздің тақтаңыз',
  'Escreva uma palavra de 5 letras.': '5 әріпті сөз жазыңыз.',
  'Essa palavra não está na lista.': 'Бұл сөз тізімде жоқ.',
  'Esta rodada já acabou.': 'Бұл раунд аяқталып қойған.',
  'O Lobisomem precisa de pelo menos 4 pessoas na sala.': 'Қасқыр-адам ойынына бөлмеде кемінде 4 адам керек.',
  'Esta partida começou sem você. Espere a próxima.': 'Бұл ойын сізсіз басталды. Келесісін күтіңіз.',
  'Quem saiu do jogo só assiste.': 'Ойыннан шыққандар тек қарайды.',
