  'O motivo (a pessoa vai ler)': 'Себебі (адам оны оқиды)',
  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'Апелляцияңыз {quando} қабылданды. Syden командасы оқып, жауап береді.',
  'O seu responsável': 'Қамқоршыңыз',
  'O seu tempo de hoje acabou': 'Бүгінгі уақытыңыз бітті',
  'O Syden é para quem tem 13 anos ou mais.': 'Syden 13 және одан үлкен жастағыларға арналған.',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden 13 және одан үлкен жастағыларға арналған. Туған күніңізді ешкім көрмейді.',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Syden енді 18 жасқа толмағандарды қорғау үшін барлығының жасын сұрайды (ECA Digital заңы). Туған күніңізді ешкім көрмейді: тек жас тобы қолданылады.',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'Кімге хабарланды және іс нөмірі (мыс.: SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'Қауіпсіздік үшін трансляциялардың алдын ала көрінісі кәмелетке толмағандарға жабық.',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'Қауіпсіздік үшін кәмелетке толмағандар жеке әңгімені тек достармен жүргізеді.',
  'Qual é a sua data de nascimento?': 'Туған күніңіз қашан?',
  'Quem muda estas regras é o seu responsável.': 'Бұл ережелерді қамқоршыңыз өзгертеді.',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': '13–15 жастағылар Syden-ді әке, ана немесе қамқоршының аккаунтына байланыстырылған аккаунтпен пайдаланады. Бұл — заң (ECA Digital), және бұл сіздің қауіпсіздігіңіз үшін.',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': '18 жасқа толмағандар Syden-ді қосымша қорғаныспен, ал 13–15 жастағылар қамқоршының аккаунтына байланыстырылған аккаунтпен пайдаланады (ECA Digital заңы).',
