  'Festa dos coelhos': 'Қояндар кеші',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Жылдам ойындардың бес раунды, әркім өз экранында: реакция, мергендік, есте сақтау және көз. Әр раундта ең жақсы болған көбірек ұпай алады.',
  'Saque rápido': 'Жылдам ату',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Белгіні күтіп, барынша жылдам басыңыз. Белгіден бұрын бассаңыз, ойыннан шығасыз.',
  'Medidor de força': 'Күш өлшегіш',
