  'Parar o relógio': 'Сағатты тоқтату',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Сағатты дәл 10 секундта тоқтатыңыз. Сандар 3-тен кейін жоғалады.',
  'Jogo dos copos': 'Стақандар ойыны',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Сәбіздің қайда екенін көріп, стақанды бақылаңыз. Неғұрлым тез тапсаңыз, соғұрлым көп ұпай.',
  'Siga o coelho': 'Қоянның соңынан еріңіз',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Көрсеткілерді ретімен қайталаңыз. Әр дұрыс жауаптан кейін тағы біреуі қосылады.',
