  'Balões': 'Шарлар',
  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'Жәшіктерді алып, басқалардың шарларын жарыңыз. Шары қалмаған ойыннан шығады.',
  'Sem balões: agora é assistir. ◀ ▶ trocam de quem.': 'Шар қалмады: енді тек көру. ◀ ▶ кімді көретінді ауыстырады.',
