  '{n} voltas': 'Айналым: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Энергия — әрі өмір, әрі турбо: шетке соғылу оны жұмсайды, қызғылт жолақ қайта толтырады.',
  'A nave explodiu: a energia acabou.': 'Кеме жарылды: энергия бітті.',
  'Posição: {posicao} de {total}': 'Орын: {posicao} / {total}',
  'Escolher a pista': 'Трасса таңдау',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Аспалы трассадағы сәбіз-кемелер жарысы, карттан әлдеқайда жылдам. Энергия — әрі өмір, әрі турбо: шетке соғылу оны жұмсайды, қызғылт жолақ қайта толтырады, ал трассадан шығу — құлау. Жеке: уақытқа және достардың елестеріне қарсы.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Жабық аренадағы карттар, әрқайсысында үш шар. Жәшіктерді алып, заттармен басқалардың шарларын жарыңыз: шары қалмаған ойыннан шығады, соңына дейін қалған жеңеді.',
  'Esquadrilha da toca': 'Іннің эскадрильясы',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Сәбіз ұшақтар бақша зиянкестеріне қарсы: тұқымдардан жалтар, көмекті жина және соңында механикалық қарақшыны атып түсір. Топ бірдей толқындармен ұшады, ал эскадрильяның ұпайлары қосылады.',
  'O espantalho caiu!': 'Қарақшы құлады!',
  'A praga venceu desta vez.': 'Бұл жолы зиянкестер жеңді.',
