  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Кемені таңдап, теңізді түртіңіз. Орнын ауыстыру үшін сүйреңіз.',
  'Sortear a frota': 'Кездейсоқ флот',
  'Sua frota já está pronta.': 'Флотыңыз дайын.',
  'Ponha todos os navios antes.': 'Алдымен барлық кемені орналастырыңыз.',
