  'Os navios não podem encostar um no outro.': 'Кемелер бір-біріне тиіспеуі керек.',
  'Minigolfe 3D': 'Миниголф 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Сегіз шұңқыр 3D-де, рампалар, қамал және жел диірмені бар, бәрі бір уақытта бірдей шұңқырды ойнайды. Көздеу мен күш беру үшін сүйреңіз де, жіберіңіз. Жалпы соққысы ең аз адам жеңеді.',
  'Ver o buraco de cima': 'Шұңқырды жоғарыдан көру',
  'Fora da pista! Mais uma tacada.': 'Жолдан шықты! Тағы бір соққы.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Көздеу үшін бүйірге, күш үшін төмен сүйреңіз де, жіберіңіз. Пернетақтада: көрсеткілер көздейді, ал басып тұрған Бос орын күш береді.',
  'Futebol dos coelhos': 'Қояндар футболы',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Шағын алаңдағы футбол, жоғарыдан. Допты алып жүру үшін оған тиіңіз, қаттырақ соғу үшін Бос орынды басып тұрыңыз, X арқылы пас беріңіз. Бөлмеде командалар роботтармен толықтырылады.',
  'Quantos por time?': 'Командада неше адам?',
