  'Caça às pragas da horta': 'Бақша зиянкестеріне аң аулау',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Қарғалар мен шегірткелер бақшаға шабуыл жасайды. Қашып кетпей тұрып, нысанаға алып шерт: оқ-дәрі санаулы, әр толқын тезірек келеді. Ең көп ұпай жинаған жеңеді.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Зиянкестер қашып кетпей тұрып, нысанаға алып шерт. Әр атыс бір сәбізді жұмсайды.',
