  '{nome} chegou à cenoura dourada.': '{nome} алтын сәбізге жетті.',
  'Quantas rodadas?': 'Неше раунд?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Қояндар бақшаны түлкілерден, қарғалардан және бір борсықтан қорғайды. Бірге жүріңіздер, комбомен соғыңыздар және бір-біріңізге қамқор болыңыздар: 1–4 адам.',
  'Pulo do coelho': 'Қоян секірісі',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Платформалық жарыс: жүгіріңіз, секіріңіз және құламаңыз. Жалғыз — сағатқа және достарыңыздың елестеріне қарсы; топпен — тікелей, бір деңгейде немесе үшеуінде де.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Үш немесе одан көп бірдей көкөніс жинау үшін көрші екі көкөністің орнын ауыстырыңыз. Үйінді тоқтаусыз көтеріледі: шыңға жеткізбеңіз. Топпен тізбектер мен комболар басқаларға жәшік жібереді.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Алты миниголф шұңқыры, бәрі бір уақытта бір шұңқырды ойнайды. Соққы жасау үшін допты артқа тартып, жіберіңіз. Барлығы ең аз соққы жинаған жеңеді.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Әркім өз кезегінде сүйекті лақтырып, бақшада алға жүреді. Алтын сәбізді сатып алу үшін сәбіз жинаңыз, әр раундтан кейін топ шағын ойын ойнайды. Ең көп алтын сәбізі бар адам жеңеді.',
  'Os pódios e as conquistas da turma': 'Тұғырлар мен топтың жетістіктері',
