  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.':
    'Бразилия астаналарын арала, қалалар сатып ал және оларға тоқтағандардан жалдау ақысын жина. Бүкіл аймақ сенде болса, ғимарат салуға болады. Айырбас жаса, аукциондарда бәсекеге түс және ақшасыз қалма.',
