  'Batalha naval': 'Теңіз шайқасы',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Кәдімгі домино, 2–4 адамға (төртеу болса, жұппен). Тастарды тізбектің ұштарына қосыңыз, кім бірінші бітірсе, қалғандардың қолындағы ұпайларды алады.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Паулиста трукосы, ашық карта мен козырьлермен, екеуара немесе төртеу жұппен. Труко жариялаңыз, алтыға, тоғызға және он екіге көтеріңіз немесе қашыңыз. 12 ұпай жинаған жеңеді.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Бразилиялық дойбы: жеу міндетті, алға да, артқа да, ал дамка бүкіл диагональ бойымен жүреді. Бөлме бақылайды.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Әркім өз флотын жасырып, басқаның теңізіне атады. Тигізсеңіз, тағы атасыз. Бүкіл флотты бірінші батырған жеңеді. Бөлме бақылайды.',
