  Xadrez: 'Шахмат',
  'Uma partida de xadrez inteira, com todas as regras. Quem abre fica com as brancas. A sala assiste.': 'Барлық ережелерімен толық шахмат ойыны. Бастаған ақпен ойнайды. Бөлме қарап отырады.',
