  Bispo: 'Піл',
  'Cozinha da toca': 'Індегі ас үй',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Жәшіктерден азық ал, тақтада тура, күйдірмей плитада және пеште пісір, табаққа сал да терезеден тапсыр. Барлығы бірдей тапсырыс алады: 3 минутта ең көп табақ тапсырған жеңеді.',
  'Pegar ou largar': 'Алу не қою',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Бұл ойынға 3D графика керек, ол бұл құрылғыда ашылмады.',
  'Este prato não é o pedido.': 'Бұл табақ тапсырыс емес.',
