  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Соңғы үш іске қосудан шектеулі Docker, SSH, logind және ядро журналдары. IP мекенжайлары болуы мүмкін.",
