  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Провайдер панеліндегі сандардың дәл өзі. Сервер өзі өлшемейтін диск те кіреді.",
  "Ações no servidor": "Сервердегі әрекеттер",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Hetzner тарихы: панельден немесе API арқылы қосу, өшіру және қайта іске қосу. Мұнда әрекеті жоқ іркіліс бұл жолдармен туындамаған.",
