  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Автоматты таңдау қателескенде: ажыратымдылық пен кадрлар таратылымның басынан аяғына дейін сен таңдағандай қалады.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Компьютеріңде жасалатын дауыс пен камера әсерлері, серверге ештеңе жібермей.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Сәбіз командосы",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Топпен бірге жүгіріп, ат: сәбіз атқыш сегіз бағытқа көздейді, граната жол ашады, ал торға қамалған кішкентай қояндарды босатқан күшейту алады. Соңында айдаһар күтіп тұр: 1-ден 4 адамға дейін.",
  'Andar e mirar': "Жүру және көздеу",
