  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Іннің зынданы",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Саңырауқұлақ патшаның інінен бірге өтіңдер: аңдарға толы бөлмелер, барып қайтатын сәбізі бар сандық, бір мезгілде екі адамды қажет ететін түймелер және құлыпталған есік. 1-ден 4 адамға дейін.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ін рингі",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Компьютердің үш қарсыласына қарсы рефлекс боксы. Әр соққының белгісін оқы, жалтар не қорған, саңылауға ұр. Қолғап жарқ еткенде ұрсаң, күшті соққының жұлдызы толады.",
