  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Жұлдыз жолы",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Ғарыш кемелеріндегі қояндар планета бетінің үстімен және ғарышта: ат, нысананы құлыптау үшін атуды басып тұр, оқтарды қайтару үшін айнал және айрықта жолды таңда. Топ бір жолмен ұшады, ал соңында бастық күтіп тұр.",
  'Pirueta': "Айналу",
