  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Далада қыдырып, биік шөптегі аңдармен сәбізбен дос бол және алтыға дейінгі команда жина. Көк үйдің сынағын жеңіп, бөлмеде досыңның командасымен шайқас.",
